insert into denri_mkt_timed_offers (month_key, seq, name, market, start_date, end_date, window_label, total_sold, total_posts, per_post, best_name, best_sold, total_stock, lift_pct, base_start, base_end, base_days, base_total, base_per_day, offer_days, offer_total, offer_per_day, verdict) values ('2026-10', 1, '9–10 Oct · Up to KES 1,400 Off (Kenya)', 'Kenya', '2026-10-09', '2026-10-10', '9–10 Oct 2026', 376, 96, 3.9, 'Mini Zuri', 88, 2092, 49, '2026-10-01', '2026-10-08', 8, 1008, 126, 2, 376, 188, '<b>Good move.</b> All six ran a real <b>15–39% cut</b> and daily sales rose <b>+49%</b> during back-to-school. The catch: <b>discount depth didn''t pick the winners</b> — the deepest cut (Zuri, -39%) sold least, while the popular school lines led. Repeat the timing; you can likely <b>trim the deepest cuts</b> on the slow movers without losing volume.');
